'use strict';
/* Attendance-wide or individual weekly-off rules and configurable paid leave. */
const attendanceCriteriaDays=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const attendanceWeeklyOffField=schemas.staff.find(field=>field.key==='weeklyOffDay');
if(attendanceWeeklyOffField){attendanceWeeklyOffField.label='Weekly Off Day (Individual)';attendanceWeeklyOffField.options=['Use Global','None',...attendanceCriteriaDays];attendanceWeeklyOffField.default='Use Global'}
if(!schemas.staff.some(field=>field.key==='paidLeaveDaysPerMonth')){const at=schemas.staff.findIndex(field=>field.key==='weeklyOffDay');schemas.staff.splice(at>=0?at+1:schemas.staff.findIndex(field=>field.key==='salaryType')+1,0,{key:'paidLeaveDaysPerMonth',label:'Paid Leave Allowance / Month',type:'number',default:0})}
const attendanceNormalizeBeforeLeave=normalizeAttendanceStatus;
normalizeAttendanceStatus=function(value){const v=String(value||'').trim().toLowerCase();if(['pl','paid leave','paidleave'].includes(v))return 'Paid Leave';if(['ul','unpaid leave','unpaidleave','weekly off','weeklyoff','wo'].includes(v))return 'Weekly Off';return attendanceNormalizeBeforeLeave(value)};
const attendanceLabelBeforeLeave=attendanceLabel;
attendanceLabel=function(status){const v=normalizeAttendanceStatus(status);return v==='Paid Leave'?'PL':v==='Weekly Off'?'WO':attendanceLabelBeforeLeave(v)};
const attendanceDailyBeforeLeave=dailyAttendanceMarkup;
dailyAttendanceMarkup=function(){return attendanceDailyBeforeLeave()};
const attendanceEstimateBeforeCriteria=attendanceSalaryEstimate;
function attendanceWeeklyOffFor(staff){const mode=db.settings.attendanceWeeklyOffMode||'all',globalDay=db.settings.attendanceGlobalWeeklyOff||'Sunday',personal=staff.weeklyOffDay||'Use Global';return mode==='all'||personal==='Use Global'?globalDay:personal}
function attendanceEligiblePaidLeaves(staff,days){const off=attendanceWeeklyOffFor(staff),offIndex=off==='None'?-1:attendanceCriteriaDays.indexOf(off),limit=Math.max(0,Math.floor(Number(staff.paidLeaveDaysPerMonth)||0));let count=0;for(const day of days){if(offIndex>=0&&new Date(day.date+'T12:00:00').getDay()===offIndex)continue;if(normalizeAttendanceStatus(attendanceFor(day.date,staff.id).status)==='Paid Leave')count++}return Math.min(limit,count)}
attendanceSalaryEstimate=function(staff,counts,days){const type=String(staff.salaryType||'').trim().toLowerCase(),amount=Number(staff.salary||0),paidLeaves=attendanceEligiblePaidLeaves(staff,days);if(type==='monthly'){const off=attendanceWeeklyOffFor(staff),offIndex=off==='None'?-1:attendanceCriteriaDays.indexOf(off),working=days.filter(day=>offIndex<0||new Date(day.date+'T12:00:00').getDay()!==offIndex),paidUnits=working.reduce((total,day)=>{const status=normalizeAttendanceStatus(attendanceFor(day.date,staff.id).status);return total+(status==='Present'||status==='Weekly Off'?1:status==='Half Day'?.5:0)},0)+paidLeaves,rate=working.length?amount/working.length:0;return {dailyRate:rate,estimated:rate*paidUnits,label:'Monthly salary ÷ scheduled working days × payable days (Weekly Off treated as a salary day)'}}if(type==='daily'){const rate=amount,unpaidLeaveDays=days.filter(day=>normalizeAttendanceStatus(attendanceFor(day.date,staff.id).status)==='Weekly Off').length;return {dailyRate:rate,estimated:rate*(counts.payable+paidLeaves+unpaidLeaveDays),label:'Daily rate × payable days (Weekly Off treated as a salary day)'}}return attendanceEstimateBeforeCriteria(staff,counts,days)};
const monthlyMarkupBeforeLeaveCriteria=monthlyAttendanceMarkup;
monthlyAttendanceMarkup=function(){let html=monthlyMarkupBeforeLeaveCriteria();return html.replace('<span class="absent">A <b>Absent (0.0)</b></span>','<span class="absent">A <b>Absent (0.0)</b></span><span class="paidleave">PL <b>Paid Leave</b></span><span class="weeklyoff">WO <b>Weekly Off</b></span>').replace('Tap a day cell to cycle its status. Changes save immediately.','Tap a day cell to cycle P, H, A, PL, WO or unmarked. PL is paid only within the staff member’s monthly allowance; Weekly Off is payable for salary.').replace('monthly salary is prorated over scheduled working days after excluding each staff member’s weekly off;','monthly salary is prorated over scheduled working days after excluding each staff member’s weekly off; eligible PL is paid within the allowance set in Staff Master; Weekly Off is payable;')};
render();
